import { useEffect, useState } from "react";
import AnimatedLetters from "../AnimatedLetters";
import useInView from "../../hooks/useInView";
import Loader from "react-loaders";
import "./index.scss";

const techIconMap = {
  react: "/tech-icons/react.svg",
  nextjs: "/tech-icons/nextjs.png",
  javascript: "/tech-icons/javascript.png",
  typescript: "/tech-icons/typescript.png",
  node: "/tech-icons/nodejs.png",
  mongodb: "/tech-icons/mongodb.svg",
  css: "/tech-icons/css.svg",
  api: "/tech-icons/api.png",
};

const techItems = [
  { key: "react", label: "React" },
  { key: "nextjs", label: "Next.js" },
  { key: "typescript", label: "TypeScript" },
  { key: "javascript", label: "JavaScript" },
  { key: "node", label: "Node.js" },
  { key: "mongodb", label: "MongoDB" },
  { key: "css", label: "CSS / SCSS" },
  { key: "api", label: "REST APIs" },
];

const About = () => {
  const [letterClass, setLetterClass] = useState("text-animate");
  const [ref, inView] = useInView();

  useEffect(() => {
    const timer = setTimeout(() => {
      setLetterClass("text-animate-hover");
    }, 3000);
    return () => clearTimeout(timer);
  }, []);

  return (
    <>
      <div
        id="about"
        ref={ref}
        className={`container about-page fade-section ${
          inView ? "in-view" : ""
        }`}
      >
        <h1 className="page-title">
          <AnimatedLetters
            letterClass={letterClass}
            strArray={"About Me:".split("")}
            index={15}
          />
        </h1>

        <div className="text-zone">
          <p>
            I&apos;m Chris, a full-stack web developer based in New York City.
            I like taking messy, real-world problems and turning them into
            clean, usable web apps.
          </p>

          <p>
            Most of my work centers around{" "}
            <span className="highlight">React</span>,{" "}
            <span className="highlight">Next.js</span>, and{" "}
            <span className="highlight">TypeScript</span> — building
            data-driven tools like fantasy sports optimizers, smarter fitness
            tracking, and utilities for the Pokémon TCG. I care a lot about
            clear UX, performance, and writing code that the next developer
            won&apos;t hate.
          </p>

          <p>
            Right now I&apos;m sharpening my back-end skills with{" "}
            <span className="highlight">Node</span>,{" "}
            <span className="highlight">APIs</span>, and{" "}
            <span className="highlight">MongoDB</span>, and looking for a role
            where I can ship real features, learn from more senior engineers,
            and contribute to a strong engineering culture.
          </p>
        </div>

        {/* Two cards row */}
        <div className="about-cards-row">
          <section className="about-card">
            <h2>Problems I&apos;m Solving</h2>
            <ul>
              <li>Shipping small, end-to-end features in real projects</li>
              <li>Deepening my TypeScript and testing habits</li>
              <li>Designing clean, predictable API contracts</li>
              <li>
                Leveling up performance, accessibility, and DX (developer
                experience)
              </li>
            </ul>
          </section>

          <section className="about-card">
            <h2>Tech I Work With</h2>
            <div className="tech-pill-row">
              {techItems.map(({ key, label }) => {
                const src = techIconMap[key];
                return (
                  <div className="tech-pill" key={key}>
                    {src && (
                      <img
                        src={src}
                        alt={label}
                        className="tech-pill-icon"
                      />
                    )}
                    <span>{label}</span>
                  </div>
                );
              })}
            </div>
          </section>
        </div>

        <p className="about-outside-text">
          Outside of coding, you&apos;ll usually find me testing Pokémon TCG
          decks, teaching chess to elementary school students, lifting, or doing
          anything that mixes strategy, teaching, and long-term improvement.
        </p>
      </div>

      <Loader type="pacman" />
    </>
  );
};

export default About;
